package p_cdbf3019a3a300007f3d219dbc66ccf3

import (
 "testing"
 "sync/atomic"
 rt "gopurs/output/gopurs_runtime"
)

// These prototypes accept a fresh contiguous range of canonical Int values,
// lower >= 2. The buffer is private; there is no ownership inference or mutation
// of a PureScript value. No input or selected leader is precomputed.

//go:noinline
func pipelineCompact(lower, upper, seed int64) int64 {
 if upper < lower { return seed }
 values := make([]int64, upper-lower+1)
 for i := range values { values[i] = lower+int64(i) }
 for len(values)>0 {
  leader:=values[0]
  seed=rt.IntAdd(seed,leader)
  count:=0
  for _, value:=range values[1:] {
   if rt.IntMod(value,leader)!=0 { values[count]=value;count++ }
  }
  values=values[:count]
 }
 return seed
}

//go:noinline
func pipelineStream(lower, upper, seed int64) int64 {
 if upper < lower { return seed }
 leaders:=make([]int64, 0, upper-lower+1)
 for value:=lower;value<=upper;value++ {
  keep:=true
  for _,leader:=range leaders { if rt.IntMod(value,leader)==0 {keep=false;break} }
  if keep { seed=rt.IntAdd(seed,value);leaders=append(leaders,value) }
 }
 return seed
}

//go:noinline
func pipelineBool(lower, upper, seed int64) int64 {
 if upper < lower { return seed }
 excluded:=make([]bool,upper-lower+1)
 for value:=lower;value<=upper;value++ {
  if excluded[value-lower] {continue}
  seed=rt.IntAdd(seed,value)
  // The remaining range contains only values > value. Its first value
  // congruent to zero modulo this leader is exactly 2*value.
  for next:=value+value;next<=upper;next+=value {excluded[next-lower]=true}
 }
 return seed
}

//go:noinline
func pipelineBits(lower, upper, seed int64) int64 {
 if upper < lower { return seed }
 excluded:=make([]uint64,(upper-lower+64)/64)
 for value:=lower;value<=upper;value++ {
  index:=value-lower
  if excluded[index>>6]&(1<<uint(index&63))!=0 {continue}
  seed=rt.IntAdd(seed,value)
  for next:=value+value;next<=upper;next+=value {
   index=next-lower
   excluded[index>>6]|=1<<uint(index&63)
  }
 }
 return seed
}

