  for _,variant:=range funcs {if got:=variant.f(2,upper,0);got!=want {t.Fatalf("%s range2..%d=%d want%d",variant.name,upper,got,want)}}
 }
 // For lower>2 this recurrence can retain composites, so prime-oracle answers
 // would be wrong. Compare against the exact generated recursive list program.
 for lower:=int64(2);lower<=50;lower++ {
  for width:=int64(-1);width<=400;width+=17 {
   upper:=lower+width
   want:=Call_Test_Primes_sumList(Call_Test_Primes_sieve(Call_Test_Primes_go__range(lower,upper)))
   for _,seed:=range []int64{0,1,-2147483648,2147483647} {
    expected:=rt.IntAdd(seed,want)
    for _,variant:=range funcs {if got:=variant.f(lower,upper,seed);got!=expected {t.Fatalf("%s %d..%d seed%d=%d want%d",variant.name,lower,upper,seed,got,expected)}}
   }
  }
 }
 for lower:=int64(2147482647);lower<=2147483647;lower+=37 {
  upper:=int64(2147483647)
  want:=Call_Test_Primes_sumList(Call_Test_Primes_sieve(Call_Test_Primes_go__range(lower,upper)))
  for _,seed:=range []int64{-4294967299,4294967301} {
