  }
 }
 for _,upper:=range []int64{2000,10000,100000,500000} {
  want:=int64(int32(sharingPrimeOracle(upper)))
  // The asymptotically identical compact/stream versions are checked on 10000;
  // progressions are also checked on 100000 without timing oracle construction.
  for i,variant:=range funcs {if upper>=100000&&i<2 {continue};if got:=variant.f(2,upper,0);got!=want {t.Fatalf("%s large%d=%d want%d",variant.name,upper,got,want)}}
 }
}

func TestPipelineOperationCounts(t *testing.T) {
 const upper=500
 excluded:=make([]bool,upper-1)
 leaders,marks,checks:=0,0,0
 for value:=int64(2);value<=upper;value++ {
  checks++
  if excluded[value-2] {continue}
  leaders++
  for next:=value+value;next<=upper;next+=value {excluded[next-2]=true;marks++}
